import XCTest
import Foundation
@testable import TechnichromeCore

/// Compares the Swift engine against the Python prototype using fixtures generated by
/// tools/colorscience/export_fixtures.py (parameters + expected outputs for a set of inputs), for the shipped
/// look and for each parameter variant the fixture carries (unequal dye D max; lights, flare and no key; the measured
/// dye sets), and the dye sets the Laboratory offers against the prototype's.
final class PythonParityTests: XCTestCase {
    struct Sample: Decodable { let input: [Double]; let dye: [Double]; let key: Double; let output: [Double]; let outputSRGB: [Double] }
    struct Variant: Decodable { let name: String; let parameters: EngineParameters; let samples: [Sample] }
    struct Fixture: Decodable {
        let parameters: EngineParameters
        let lutDimension: Int
        let displaySpace: String
        let samples: [Sample]
        let variants: [Variant]
        let dyeSets: [DyeSetPreset]
    }

    func loadFixture() throws -> Fixture? {
        guard let url = Bundle.module.url(forResource: "parity", withExtension: "json", subdirectory: "Fixtures") else { return nil }
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    /// Both sides compute in float64; what differs is the Swift cube's Float32 storage (about 1.6e-8 on the output)
    /// and rounding in the curves (about 1e-15 on the densities), well inside these bounds.
    static let densityTolerance = 1e-7
    static let outputTolerance = 1e-6

    /// Checks one block of the fixture; returns the worst density and output errors (the P3 print and the sRGB print).
    func check(_ parameters: EngineParameters, _ samples: [Sample], fixture f: Fixture, name: String) -> (density: Double, output: Double) {
        let space: PrintModel.DisplaySpace = f.displaySpace == "srgb" ? .sRGB : .displayP3
        let pipe = ReferencePipeline(parameters: parameters, lutDimension: f.lutDimension, displaySpace: space)
        let srgb = ReferencePipeline(parameters: parameters, lutDimension: f.lutDimension, displaySpace: .sRGB)
        var worstDensity = 0.0, worstOutput = 0.0
        for s in samples {
            let input = SIMD3(s.input[0], s.input[1], s.input[2])
            let (dye, key) = pipe.densities(sceneLinear: input)
            XCTAssertEqual(dye.x, s.dye[0], accuracy: Self.densityTolerance, "\(name): cyan density for \(s.input)")
            XCTAssertEqual(dye.y, s.dye[1], accuracy: Self.densityTolerance, "\(name): magenta density for \(s.input)")
            XCTAssertEqual(dye.z, s.dye[2], accuracy: Self.densityTolerance, "\(name): yellow density for \(s.input)")
            XCTAssertEqual(key, s.key, accuracy: Self.densityTolerance, "\(name): key density for \(s.input)")
            worstDensity = max(worstDensity, abs(dye.x - s.dye[0]), abs(dye.y - s.dye[1]), abs(dye.z - s.dye[2]), abs(key - s.key))
            let out = pipe.develop(sceneLinear: input)
            let outSRGB = srgb.develop(sceneLinear: input)
            for i in 0..<3 {
                worstOutput = max(worstOutput, abs(out[i] - s.output[i]), abs(outSRGB[i] - s.outputSRGB[i]))
                XCTAssertEqual(out[i], s.output[i], accuracy: Self.outputTolerance, "\(name): output channel \(i) for \(s.input)")
                XCTAssertEqual(outSRGB[i], s.outputSRGB[i], accuracy: Self.outputTolerance, "\(name): sRGB print channel \(i) for \(s.input)")
            }
        }
        return (worstDensity, worstOutput)
    }

    /// The presets are tcengine.DYE_SETS, the shipped look carries Technichrome v1's, and each measured set's fixture
    /// block is the shipped look with that set's dyes and gains.
    func testDyeSetsAreThePrototypes() throws {
        guard let f = try loadFixture() else { throw XCTSkip("no parity fixture generated yet") }
        XCTAssertEqual(EngineParameters.dyeSets, f.dyeSets)
        XCTAssertEqual(EngineParameters.default.dyeSet?.name, "Technichrome v1")
        for (set, block) in [("US 1949 (Samson and Delilah)", "US 1949 dyes"), ("UK (NSMM 12593)", "UK dyes")] {
            let preset = try XCTUnwrap(EngineParameters.dyeSets.first { $0.name == set })
            let variant = try XCTUnwrap(f.variants.first { $0.name == block })
            var p = EngineParameters.default
            p.useDyeSet(preset)
            XCTAssertEqual(p.dyeSet, preset)
            p.name = variant.parameters.name
            XCTAssertEqual(p, variant.parameters, "\(set): the shipped look with this dye set")
        }
    }

    func testMatchesPythonPrototype() throws {
        guard let f = try loadFixture() else {
            throw XCTSkip("no parity fixture generated yet")
        }
        let shipped = check(f.parameters, f.samples, fixture: f, name: "shipped look")
        print("max |Swift - Python| density error: \(shipped.density), output error: \(shipped.output)")
        XCTAssertFalse(f.variants.isEmpty, "the fixture carries parameter variants")
        for v in f.variants {
            let e = check(v.parameters, v.samples, fixture: f, name: v.name)
            print("max |Swift - Python| for \(v.name): density error \(e.density), output error \(e.output)")
        }
    }
}
